{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "A close nicotine-like analogue showed a rat brain-to-blood ratio of 1.9 within 30 s and was classified as BBB-permeable, supporting rapid CNS access for the query's basic heteroaromatic amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nicotine itself had a Brain Uptake Index of 125 in rats after intracarotid injection, demonstrating that this nicotine-related azabicyclic/heteroaromatic amine class readily crosses the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "AN317, a structurally related nicotine analogue, showed high brain-to-plasma ratios in mice and rats after subcutaneous dosing, providing direct evidence of meaningful CNS exposure for this chemical family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "L-670,548, a methyl oxadiazole in the 1-azanorbornane series, showed excellent brain penetration with 3.8% of the administered dose reaching the brain, directly supporting the CNS penetrability of the oxadiazole-azabicyclic combination present in the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A related azabicyclic heteroaromatic ligand, [18F]AZAN, exhibited remarkably high brain uptake in baboon and human PET studies, confirming that this compound class achieves robust CNS exposure in higher species.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query combines a lipophilic N-methylpyrrole, an oxadiazole, and a basic diazabicyclooctane, closely resembling nicotine-like azabicyclic CNS ligands. All high-transfer experimental analogues show rapid and substantial brain penetration across species, with no evidence of an efflux or poor-penetration liability. Therefore the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement is available for the exact query molecule.",
    "No explicit P-glycoprotein or BCRP efflux data are available for the query, though the consistent high-penetration analogue data outweigh this uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

